export type Ember = WasmDevice<typeof EMBER_PARAMS>

/** Subtractive pad synth: two oscillators with hard sync, sub and noise through a 12/24 dB filter with its own envelope, two LFOs, glide and up to eight detuned unison voices spread across the stereo field. Play it through `NoteDevice`: `noteOn(id, frequency, gain)` / `noteOff(id)`. */
export function createEmber(
  context: BaseAudioContext,
  options: WasmDeviceOptions<typeof EMBER_PARAMS> = {},
): Promise<Ember> {
  return WasmDevice.create(context, EMBER_DEVICE, options)
}
